import{_ as i,o as a,c as t,ag as e}from"./chunks/framework.TQKaXlFR.js";const c=JSON.parse('{"title":"备份与恢复","description":"","frontmatter":{},"headers":[],"relativePath":"operations/backup-restore.md","filePath":"operations/backup-restore.md"}'),n={name:"operations/backup-restore.md"};function h(l,s,p,r,d,k){return a(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="备份与恢复" tabindex="-1">备份与恢复 <a class="header-anchor" href="#备份与恢复" aria-label="Permalink to &quot;备份与恢复&quot;">​</a></h1><p>本页向数据库和部署维护人员说明一致性恢复需要保存的对象。前提是有当前环境的维护权限、保密存储位置和经过评估的恢复窗口；不要在共享数据库或别人环境照抄恢复命令。</p><h2 id="备份集合" tabindex="-1">备份集合 <a class="header-anchor" href="#备份集合" aria-label="Permalink to &quot;备份集合&quot;">​</a></h2><table tabindex="0"><thead><tr><th>内容</th><th>原因</th></tr></thead><tbody><tr><td>数据库及 <code>flyway_schema_history</code></td><td>业务数据、权限、已应用版本与校验和必须成套恢复</td></tr><tr><td>原始 <code>CONFIG_MASTER_KEY</code></td><td>数据库密文的解密依赖它；新随机主密钥不能解密旧数据</td></tr><tr><td>JWT密钥/服务端配置版本</td><td>恢复时决定会话有效性和基础设施连接</td></tr><tr><td>对象存储对象及历史平台配置</td><td>文件记录对应对象；不能只备份SQL或只备份当前bucket配置</td></tr><tr><td>前后端/文档代码与产物摘要</td><td>确认能与恢复数据库一致运行的版本</td></tr><tr><td>Redis恢复/会话策略</td><td>明确保留缓存或让会话重新认证，不意外恢复已失效登录态</td></tr></tbody></table><p>微信、短信、存储、模型的数据库凭据使用AES-GCM密文；备份SQL不等于备份完整运行能力。主密钥与数据库分别受控保存，在恢复审批中配对，不能把密钥一并放到公开发布包。</p><h2 id="建立一致性窗口" tabindex="-1">建立一致性窗口 <a class="header-anchor" href="#建立一致性窗口" aria-label="Permalink to &quot;建立一致性窗口&quot;">​</a></h2><p>规划备份时暂停写入/调度或按数据库、对象存储的一致性策略建立恢复点。<code>mysqldump --single-transaction</code>适用于事务表逻辑快照，不自动冻结并发DDL，也不为外部对象提供跨服务事务。是否需要binlog/PITR、对象版本化与更严格RPO由运维方案决定，本项目没有自动跨服务恢复工具。</p><p>下面是单个专属schema的逻辑备份示例。使用交互式凭据配置，避免把密码放在命令行和shell历史；替换服务器/账号/目录。</p><div class="language-bash vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">umask</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 077</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mysql_config_editor</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --login-path=xinghui-backup</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --host=127.0.0.1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --user=your_backup_user</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --password</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mysqldump</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --login-path=xinghui-backup</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --single-transaction</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --default-character-set=utf8mb4</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --routines</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --triggers</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --events</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --hex-blob</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-tablespaces</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --set-gtid-purged=OFF</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xinghui_admin</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xinghui_admin-backup.sql</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sha256sum</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xinghui_admin-backup.sql</span></span></code></pre></div><p>备份账户所需权限按实际MySQL版本、对象与GTID设置核对；上述是逻辑恢复示例，不包含完整PITR方案。确认命令退出码、文件非空与摘要，把备份加密后传入受控存储，并记录对象存储同一恢复点。</p><h2 id="在隔离环境演练恢复" tabindex="-1">在隔离环境演练恢复 <a class="header-anchor" href="#在隔离环境演练恢复" aria-label="Permalink to &quot;在隔离环境演练恢复&quot;">​</a></h2><p>不要直接覆盖生产。先建立新的隔离schema及恢复账号，使用<strong>恢复权限</strong>的另一个login-path：</p><div class="language-sql vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DATABASE</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> xinghui_restore</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> CHARACTER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> utf8mb4 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COLLATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> utf8mb4_general_ci;</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mysql_config_editor</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --login-path=xinghui-restore</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --host=127.0.0.1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --user=your_restore_user</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --password</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mysql</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --login-path=xinghui-restore</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --database=xinghui_restore</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xinghui_admin-backup.sql</span></span></code></pre></div><p>备份命令未使用 <code>--databases</code>，不应包含切回生产库的USE/CREATE DATABASE；演练前仍检查SQL来源和目标。恢复对象快照及私有配置，使用备份对应主密钥，将应用 <code>DB_URL</code> 指向恢复库，Redis/存储也使用演练自己的目标，防止演练应用写生产服务。</p><p>使用备份对应的后端代码/迁移location启动，执行strict validate。先验证history、核心表、权限与密文解密，再用自己的低敏文件验证对象读取；供应商默认关闭，不通过发短信/模型调用证明数据库恢复。通过<a href="./../guide/verification.html">启动验证</a>完成最小认证和页面核对后记录结论。</p><h2 id="回退条件" tabindex="-1">回退条件 <a class="header-anchor" href="#回退条件" aria-label="Permalink to &quot;回退条件&quot;">​</a></h2><p>仅回退JAR不保证兼容已执行的新迁移。确认旧代码能读新schema才考虑代码回退；否则成套恢复旧DB、对象、主密钥、配置和前后端配对，必要时损失的窗口数据需由业务确认。不要用删除history或降低validate来伪造旧版可用。</p><p>主密钥丢失时，数据库中的旧密文不能靠新密钥恢复。当前没有批量轮换/重加密功能；应优先恢复原密钥，否则按受控方案重新设置相关凭据，并承认旧密文不能解密。错误主密钥与存储endpoint不可达是不同故障，见<a href="./troubleshooting.html">故障排查</a>。</p><h2 id="验证结果与源码" tabindex="-1">验证结果与源码 <a class="header-anchor" href="#验证结果与源码" aria-label="Permalink to &quot;验证结果与源码&quot;">​</a></h2><p>预期是恢复库strict校验成功、业务记录与对象能够读取、密钥不泄露、测试夹具只在演练环境。此文档只提供指南，本次文档任务没有重新备份或恢复用户业务库，也没有把空库测试冒充存量库灾备演练。</p><p>源码：<code>common/common-core/src/main/java/com/xinghuiTec/config/SecretCipher.java</code>、<code>system-admin/src/main/java/com/xinghuiTec/businessconfig/BusinessConfigService.java</code>、<code>ai/model/AiModelCredentialService.java</code>；<code>common/common-oss/src/main/java/com/xinghuiTec/oss/</code>下的历史存储解析/对象记录实现；<code>system-admin/src/main/resources/application.yml</code>与<code>db/{migration,optional-migration}/</code>。</p>`,22)])])}const g=i(n,[["render",h]]);export{c as __pageData,g as default};
